const gate=r=>{const L=D.items.filter(i=>i.status!=='Under Review').length,R=D.items.filter(i=>i.status==='Returned').length,F=D.items.filter(i=>i.type==='found'&&i.status!=='Returned').length,reg=r==='register',fl=(n,t,p,ph2,x)=>`<div class="fld">${ic(p,18)}<input name="${n}" type="${t}" placeholder="${ph2}" required ${x||''}>${t==='password'?'<button type="button" class="eye" data-a="eye">Show</button>':''}</div>`;
return `<div class="gate"><section class="gl"><div class="orb"><i class="rg r1"></i><i class="rg r2"></i><i class="rg r3"></i><i class="sweep"></i><i class="sat"></i><i class="core"></i></div><div class="hud">● SECURE ACCESS TERMINAL</div><h1>Lost it.<br><span class="glow">Trace it back.</span></h1><p class="mu" style="max-width:380px">Photo-first lost &amp; found with human-verified claims and a traceable return trail.</p><div class="gstats"><div><b>${L}</b>signals</div><div><b>${F}</b>awaiting owners</div><div><b>${R}</b>returned</div></div></section>
<section><div class="ac"><div class="ai"><div class="tabs ${reg?'r':''}"><i></i><a href="#login" class="${reg?'':'on'}">Sign in</a><a href="#register" class="${reg?'on':''}">Register</a></div><form data-f="${r}">${reg?`<label>Full name</label>${fl('name','text','<circle cx="24" cy="15" r="8"/><path d="M8 42c2-10 30-10 32 0"/>','Your name','maxlength="60"')}`:''}<label>CPUT email</label>${fl('email','email','<rect x="6" y="11" width="36" height="26" rx="4"/><path d="M6 15l18 13 18-13"/>','you@mycput.ac.za')}<label>Password</label>${fl('pw','password','<rect x="9" y="21" width="30" height="21" rx="4"/><path d="M16 21v-6a8 8 0 0116 0v6"/>',reg?'8+ characters':'Your password',reg?'minlength="8" data-m="1"':'')}${reg?'<div class="meter" id="meter" data-s="0"><i></i><i></i><i></i><i></i></div>':''}<p><button class="btn" style="width:100%;padding:13px">${reg?'Create account':'Sign in'} →</button></p></form>
<p class="mu sm">Students: use your @mycput.ac.za address. Staff may use @cput.ac.za.</p></div></div></section></div>`};
V.login=()=>gate('login');V.register=()=>gate('register');
addEventListener('input',e=>{const t=e.target;if(t.dataset&&t.dataset.m){let s=0,v=t.value;if(v.length>=8)s++;if(/[A-Z]/.test(v)&&/[a-z]/.test(v))s++;if(/\d/.test(v))s++;if(/[^\w]/.test(v)&&v.length>=10)s++;const m=$('#meter');if(m)m.dataset.s=v?s:0}});
addEventListener('change',async e=>{const t=e.target,id=t.dataset&&t.dataset.ph,u=me();if(t.dataset&&t.dataset.bulk&&u&&u.role==='admin'){const L=[...D.items].sort((a,b)=>a.id-b.id);let k=0,ok=0;for(const f of [...t.files].slice(0,L.length)){try{const p=await shrink(f);if(p){L[k].photo=p;ok++}}catch(m){}k++}log(0,u.id,`Bulk photos applied (${ok})`);save();toast(ok+' photos applied');rr();return}if(!id||!u)return;const i=D.items.find(x=>x.id===+id);if(!i||(i.owner!==u.id&&u.role!=='admin'))return;try{const p=await shrink(t.files[0]);if(!p)return;i.photo=p;log(i.id,u.id,'Photo updated');save();toast('Photo updated');rr()}catch(m){toast(m)}});
