const SV=p=>`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`,SUN=SV('<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.4 1.4M17.6 17.6L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/>'),MOON=SV('<path d="M20 14.5A8.5 8.5 0 119.5 4a7 7 0 0010.5 10.5z"/>');
const isDark=()=>getComputedStyle(document.documentElement).colorScheme==='dark';
const tgIcon=()=>{const t=$('#tg');if(t)t.innerHTML=isDark()?SUN:MOON};
const setTheme=()=>{const n=isDark()?'light':'dark';document.documentElement.dataset.theme=n;try{localStorage.setItem('ct.theme',n)}catch(e){}tgIcon()};
new MutationObserver(tgIcon).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});tgIcon();
const CH={msgs:[],busy:0,ctl:null};
const chSys=()=>{const u=me(),L=D.items.filter(pub).slice(0,40).map(i=>`${i.ref} | ${i.type} | ${i.name} | ${i.cat} | ${i.loc} | ${i.status} | ${fmt(i.created)}`).join('\n');return ['You are Trace, the assistant inside CAMPUS TRACE, a campus lost & found app with human-verified claims.','Be concise and friendly (max 90 words). Help people find items from the public list below, report items, and understand the process: report, claim with private verification answers, owner or admin approves/rejects/requests more info, safe return, return confirmed.','Never ask for or reveal passwords, PINs, serial numbers, private details or verification answers. Never approve claims; only a human owner or admin can. For ID documents and valuables, advise handing over via campus security. If the list has no match, suggest reporting the item. Only use the data below; do not invent items.',`Viewer: ${u?u.role+' (signed in)':'not signed in'}.`,'Public listings (ref | type | name | category | location | status | date):',L||'(none yet)'].join('\n')};
const chToggle=v=>{const c=$('#chat'),o=v===undefined?!c.classList.contains('on'):v;c.classList.toggle('on',o);c.setAttribute('aria-hidden',!o);if(o){if(!$('#cmsgs').children.length)chHello();setTimeout(()=>$('#cin').focus(),250)}};
const chMk=(r,x)=>{const m=$('#cmsgs'),d=document.createElement('div');d.className='cm '+r;d.textContent=x;m.appendChild(d);m.scrollTop=m.scrollHeight;return d};
const chHello=()=>{chMk('assistant','Hi, I’m Trace. Ask me to find an item or explain how claims work.');const q=document.createElement('div');q.className='cq';q.innerHTML=['How do claims work?','Any laptops found?','I lost my keys'].map(t=>`<button type="button" class="chip" data-c="q">${t}</button>`).join('');$('#cmsgs').appendChild(q)};
async function ask(t){t=(t||'').trim();if(!t||CH.busy)return;const q=$('#cmsgs .cq');if(q)q.remove();CH.msgs.push({role:'user',content:t});chMk('user',t);const el=chMk('assistant t','…'),m=$('#cmsgs');CH.busy=1;CH.ctl=new AbortController();
try{const s=window.claude&&await window.claude.use('sample');if(!s)throw{code:'na'};const inp=CH.msgs.map((x,i)=>i?x:{role:'user',content:chSys()+'\n\nUser question: '+x.content});
const r=await s(inp,{onText:({text})=>{el.classList.remove('t');el.textContent=text;m.scrollTop=m.scrollHeight},signal:CH.ctl.signal,cache:false});el.classList.remove('t');el.textContent=r.text;CH.msgs.push({role:'assistant',content:r.text})}
catch(e){CH.msgs.pop();el.classList.remove('t');el.textContent=e&&e.name==='AbortError'?'Stopped.':e&&e.code==='rate_limited'?'Too many requests. Try again shortly.':'The assistant isn’t available right now.'}
CH.busy=0}
document.addEventListener('click',e=>{const b=e.target.closest('[data-c]');if(!b)return;const c=b.dataset.c;if(c==='tog')chToggle();else if(c==='x')chToggle(false);else if(c==='clr'){if(CH.ctl)CH.ctl.abort();CH.msgs=[];CH.busy=0;$('#cmsgs').innerHTML='';chHello()}else if(c==='q')ask(b.textContent)});
$('#cform').addEventListener('submit',e=>{e.preventDefault();const i=$('#cin'),v=i.value;i.value='';ask(v)});
